956	// Samples random tracks from Tier 1 with channel_name and hazard_level cap support
957	// =============================================================================
958	export async function fetchSampledTracks(
959	  projectId: string,
960	  limit = 50,
961	  channelName?: string,
962	  hazardCap?: number | string | null,
963	  excludeChannel?: string | string[] | null
964	): Promise<{
965	  tracks: PlaylistItem[];
966	  totalCatalogCount: number;
967	  statsMap: Record<string, import('../types').TrackDisplayMeta>;
968	}> {
969	  const samplePayload: any = { limit };
970	  if (channelName && channelName !== 'ALL') {
971	    samplePayload.channel_name = channelName;
972	  }
973	  if (excludeChannel && excludeChannel !== 'NONE' && excludeChannel !== 'ALL') {
974	    samplePayload.exclude_channel = excludeChannel;
975	  }
976	  if (hazardCap !== undefined && hazardCap !== null && hazardCap !== 'ALL' && hazardCap !== 'NONE') {
977	    samplePayload.hazard_cap = hazardCap;
978	  }
979	
980	  const countPayload: any = {};
981	  if (channelName && channelName !== 'ALL') {
982	    countPayload.channel_name = channelName;
983	  }
984	  if (excludeChannel && excludeChannel !== 'NONE' && excludeChannel !== 'ALL') {
985	    countPayload.exclude_channel = excludeChannel;
986	  }
987	  if (hazardCap !== undefined && hazardCap !== null && hazardCap !== 'ALL' && hazardCap !== 'NONE') {
988	    countPayload.hazard_cap = hazardCap;
989	  }
990	
991	  const [sampleRes, countRes, t4Res, channelStateMap] = await Promise.all([
992	    executeOrder<Record<string, Record<string, unknown>>>({
993	      project_id: projectId,
994	      tier: '1',
995	      order: { action: 'sample', data: samplePayload },
996	    }),
997	    executeOrder<{ count: number }>({
998	      project_id: projectId,
999	      tier: '1',
1000	      order: { action: 'count', data: countPayload },
1001	    }),
1002	    executeOrder<Record<string, Record<string, unknown>>>({
1003	      project_id: projectId,
1004	      tier: '4',
1005	      order: { action: 'read_all' },
1006	    }),
1007	    fetchChannelState(projectId),
1008	  ]);
1009	
1010	  const statsMap: Record<string, import('../types').TrackDisplayMeta> = {};
1011	  if (t4Res.data) {
1012	    Object.entries(t4Res.data).forEach(([id, val]) => {
1013	      let played = 0;
1014	      let hazard_level = 3.0;
1015	      let timeblock: string | null = null;
1016	      let unlock_date: string | null = null;
1017	
1018	      if (val && typeof val === 'object' && !Array.isArray(val)) {
1019	        const v = val as Record<string, unknown>;
1020	        played = Number.isInteger(v.played)
1021	          ? (v.played as number)
1022	          : parseInt(String(v.played || 0), 10);
1023	        const rawHazard = Number(v.hazard_level);
1024	        hazard_level = !isNaN(rawHazard) ? rawHazard : 3.0;
1025	        timeblock = (v.timeblock as string) || null;
1026	        unlock_date = (v.unlock_date as string) || null;
1027	      } else if (val !== null && val !== undefined) {
1028	        played = parseInt(String(val), 10);
1029	      }
1030	
1031	      statsMap[String(id)] = {
1032	        played: Number.isFinite(played) && played >= 0 ? Math.floor(played) : 0,
1033	        hazard_level: Math.round(hazard_level * 100) / 100,
