3	interface SharedButtonProps {
4	  variant?: 'primary' | 'secondary' | 'danger' | 'ghost';
5	  size?: 'sm' | 'md' | 'lg';
6	  children: React.ReactNode;
7	  onClick?: () => void;
8	  disabled?: boolean;
9	  loading?: boolean;
10	  className?: string;
11	  style?: React.CSSProperties;
12	}
13	
14	export const SharedButton: React.FC<SharedButtonProps> = ({
15	  variant = 'primary',
16	  size = 'md',
17	  children,
18	  onClick,
19	  disabled = false,
20	  loading = false,
21	  className = '',
22	  style,
23	}) => {
24	  // Base classes with snappy hardware-accelerated transitions and tactile active feedback
25	  const baseClasses = `flex items-center justify-center gap-2 rounded-lg font-cinzel font-bold transition-[transform,opacity,background-color,border-color,box-shadow] duration-75 ease-out select-none cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed disabled:active:scale-100`;
26	
27	  // Variant classes
28	  const variantClasses = {
29	    primary: `bg-[#ffd86b] text-black hover:bg-[#ffd86b]/90 active:scale-[0.98]`,
30	    secondary: `bg-[#1a1424] text-[#ffd86b] hover:bg-[#1a1424]/80 border border-[#ffd86b]/40 active:scale-[0.98]`,
31	    danger: `bg-[#ff6b6b] text-white hover:bg-[#ff6b6b]/90 active:scale-[0.98]`,
32	    ghost: `text-[#ffd86b] hover:bg-[#1a1424]/40 active:scale-[0.98]`,
33	  };
34	
35	  // Size classes
36	  const sizeClasses = {
37	    sm: `px-3 py-1.5 text-xs`,
38	    md: `px-5 py-2.5 text-sm`,
39	    lg: `px-8 py-4 text-base`,
40	  };
41	
42	  // Loading spinner class
43	  const loadingClass = loading ? `animate-spin` : '';
44	
45	  const classes = [
46	    baseClasses,
47	    variantClasses[variant],
48	    sizeClasses[size],
49	    loadingClass,
50	    className,
51	  ]
52	    .filter(Boolean)
53	    .join(' ');
54	
55	  return (
56	    <button
57	      className={classes}
58	      onClick={disabled || loading ? undefined : onClick}
59	      disabled={disabled || loading}
